import{_ as o,l,o as a,c as n,v as r,p as s,x as t,d as h,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"欧拉回路","description":"","frontmatter":{"title":"欧拉回路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/euler-circuit.md","filePath":"cs/euler-circuit.md","lastUpdated":1789023840000}'),p={name:"cs/euler-circuit.md"};function u(_,e,E,m,f,A){const i=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="欧拉回路" tabindex="-1">欧拉回路 <a class="header-anchor" href="#欧拉回路" aria-label="Permalink to &quot;欧拉回路&quot;">​</a></h1><div class="epigraph"><p>每条边恰好走一次并回到起点：无向图要求连通且度数皆偶；有向图要求弱连通且入度等于出度。Hierholzer 一次扫描拼出回路。</p><footer>—— 据 Euler, 1736；Hierholzer, Über die Möglichkeit, einen Linienzug ohne Wiederholung und ohne Unterbrechung zu umfahren, 1873；CLRS 练习与标准图论整理</footer></div><p>上一课<a href="/cs/two-sat">2-SAT</a>把公式收成蕴涵图的 SCC。本课对象换成<strong>边的遍历</strong>：一笔画是否存在，以及如何构造。不重做强连通判定——有向欧拉需要「底图连通且度平衡」，比 SCC 弱一点、条件不同。缺口是充分必要条件 + 线性构造，不是哈密顿（那是下一课，点要恰好一次）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧拉回路：闭迹，含每条边恰好一次。欧拉路：开迹，同样用尽边。无向连通（忽略孤立点）：回路 \\(\\Leftrightarrow\\) 全偶度；路 \\(\\Leftrightarrow\\) 恰两个奇度（或零，退回回路）。有向：底图弱连通，且每个点入度 \\(=\\) 出度则有回路；恰一顶点出度多 \\(1\\)、一顶点入度多 \\(1\\) 则有路。</p><p>Königsberg 七桥是反例：奇度多于两个。缺口是判定之后<strong>构造</strong>：Hierholzer 从当前点沿未用边走，走不动则该点局部已用尽；把子回路接到先前断点上。Fleury 每次不走桥除非无奈，正确但实现烦，本课不主写。</p><h3 id="边一次不是点一次" tabindex="-1">边一次不是点一次 <a class="header-anchor" href="#边一次不是点一次" aria-label="Permalink to &quot;边一次不是点一次&quot;">​</a></h3><p>哈密顿回路要求每个点恰好一次，NPC。欧拉在边。不要把「看起来都走遍」混名。中国邮路在欧拉基础上加重复边，本课点名不展开。</p><p><span class="marginnote">Euler 1736 判 Königsberg。Hierholzer 1873 给出构造。有向情形与欧拉回路定理同一精神。后课 Held–Karp 才碰哈密顿的指数 DP。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检查连通与度。从起点（有向则任意平衡点）做栈：反复沿剩余出边走，无边可走则弹栈写入答案（倒序即回路）。邻接表用迭代器或删边，总 \\(O(E)\\)。</p>',11)),(a(),s(c,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEG%5B%22%E5%BA%A6%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20CONN%5B%22%E8%BF%9E%E9%80%9A%22%5D%0A%20%20CONN%20--%3E%20H%5B%22Hierholzer%20%E6%8B%BC%E5%AD%90%E5%9B%9E%E8%B7%AF%22%5D%0A%20%20H%20--%3E%20CIR%5B%22%E6%AC%A7%E6%8B%89%E5%9B%9E%E8%B7%AF%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>多重边、自环合法。不连通且有边则无。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>度偶保证每次进入能离开，直到回到起点；连通保证没有边落在圈外。Hierholzer 的正确性：走不动时当前点的局部边已用尽，剩余边落在已访点的另一连通块，再从栈里较早的点接着走。与 DFS 不同：这里消耗的是边，不是点的颜色。</p><p>混合图（有向+无向）的欧拉判定更细，本课不写。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证哈密顿、不写 TSP。不处理带权中国邮路的匹配归约（那是一般图匹配）。后课默认：欧拉回路线性可判定、可构造。下一课点的哈密顿与精确 TSP，复杂度跳到指数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧拉：边恰好一次；条件是连通加度平衡。</li><li>Hierholzer 线性构造，不是 NPC 的哈密顿。</li><li>有向、无向条件对称：入出度或奇偶。</li><li>出处：Euler, 1736；Hierholzer, 1873。</li></ul>',8))])}const B=o(p,[["render",u]]);export{g as __pageData,B as default};
